import {config,scenes} from './data/content.js';
import {next,prev,jump,fromHash,elapsed,toggleTimer,acceptsMessage} from './state.js';
import {article,button,esc,sourceCard} from './scenes.js';
const $=(q,root=document)=>root.querySelector(q);
const safeRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{}};
const params=new URLSearchParams(location.search),presenter=params.get('view')==='presenter';
let session=params.get('session');
if(!session){try{session=sessionStorage.getItem('lykeion-session')||crypto.randomUUID();sessionStorage.setItem('lykeion-session',session);}catch{session=crypto.randomUUID();}}
const sender=crypto.randomUUID(),storageKey='lykeion-'+session;
let channel;try{channel=new BroadcastChannel(storageKey);}catch{}
let notes=[],lines=[],mode=presenter?'presenter':(matchMedia('(max-width:640px)').matches?'read':'present');
let state={...fromHash(location.hash,scenes),vote:null,mesotes:1,life:2,example:0,reduced:safeRead('lykeion-motion',null)??matchMedia('(prefers-reduced-motion: reduce)').matches,names:safeRead('lykeion-names',config.presenters),timer:{elapsed:0,startedAt:0,running:false}};
let lastRendered=-1,lastStep=-1,modal=null,returnFocus=null,gesture=null,lastGestureGood=true,touchCount=0,lastRevision=0;
const app=$('#app');
const speaker=s=>s.speaker==='AB'?`${state.names.A} & ${state.names.B}`:state.names[s.speaker];
function adaptCue(i){return {3:'Das Schema schrittweise aufbauen; Hunger, Wunsch und faire Entscheidung über die drei Beispielbuttons hervorheben.',5:'Die drei Reaktionen auswählen. Kurz fragen: Warum kann Hilfeholen mutig sein?',6:'Die drei Stationen mit Hilfsbereitschaft verbinden.',7:'Lebensformen auswählen und Beispiele ausdrücklich als heutige Übertragung benennen.',14:'Diese Szene am Ende stehen lassen. N1–N3 sind ergänzte KI-Illustrationen vom 21.09.2026.'}[i]||notes[i]?.cue||'';}
function shell(){app.innerHTML=`<a class="skip-link" href="#stage">Zum Inhalt</a><header class="topbar"><a class="brand" href="#01" data-action="start"><b>α</b><span>LYKEION</span><small>ARISTOTELES & DAS GUTE LEBEN</small></a><nav class="top-actions" aria-label="Ansichten">${button('Übersicht','overview','title="Übersicht (G)"')}${button('Lesemodus','read','id="mode-button"')}<a class="presenter-link" href="?view=presenter&session=${session}" data-action="presenter" target="lykeion-presenter">Sprecheransicht ↗</a>${button('⋯','settings','aria-label="Einstellungen und Hilfe"')}</nav></header><main id="stage" class="stage" tabindex="-1"></main><footer class="controls"><div class="progress-label"><strong id="counter"></strong><span id="step-label"></span></div><div class="progress-track" aria-label="Szenen"></div><div class="nav-buttons">${button('←','prev','aria-label="Vorheriger Schritt"')}${button('Quellen','source-scene','title="Quellen (Q)"')}${button('⛶','fullscreen','aria-label="Vollbild" title="Vollbild (F)"')}${button('Weiter →','next','class="next-button"')}</div></footer><div class="input-hint">Leertaste oder freie Fläche antippen: weiter · Pfeil links: zurück ${button('×','dismiss-hint','aria-label="Bedienhinweis schließen"')}</div><dialog id="overlay" aria-labelledby="dialog-title"><div class="dialog-top"><h2 id="dialog-title"></h2>${button('×','close','aria-label="Ansicht schließen"')}</div><div id="dialog-content"></div></dialog><div class="sr-only" aria-live="polite" id="announcement"></div><div id="print-content"></div>`;
 $('#overlay').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
 $('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
 $('.progress-track').innerHTML=scenes.map((s,i)=>button(s.id,'jump',`data-index="${i}" aria-label="Szene ${i+1}: ${esc(s.title)}"`)).join('');
 buildPrint();
 $('.stage').addEventListener('pointerdown',e=>{if(e.pointerType==='touch')touchCount++;gesture={x:e.clientX,y:e.clientY,time:Date.now(),id:e.pointerId};lastGestureGood=touchCount<=1;});
 $('.stage').addEventListener('pointermove',e=>{if(gesture&&Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y)>12)lastGestureGood=false;});
 $('.stage').addEventListener('pointerup',e=>{if(e.pointerType==='touch')touchCount=Math.max(0,touchCount-1);if(gesture&&Date.now()-gesture.time>650)lastGestureGood=false;});
 $('.stage').addEventListener('pointercancel',()=>{touchCount=0;lastGestureGood=false;});
 $('.stage').addEventListener('click',e=>{if(mode!=='present'||modal||e.button!==0||!lastGestureGood||getSelection()?.toString()||e.target.closest('button,a,input,select,textarea,summary,[role="tab"],[contenteditable]'))return;act('next');});
}
function buildPrint(){$('#print-content').innerHTML=scenes.map((s,i)=>`<section class="print-page">${article(i,state)}<p>${esc(s.explanation)}</p><p class="print-refs">${esc(notes[i]?.refs||'')}</p><details open><summary>Sprechtext · ${esc(speaker(s))}</summary><p>${esc(notes[i]?.notes||'')}</p></details></section>`).join('');}
function applySteps(){const s=scenes[state.scene];document.querySelectorAll('#stage .reveal').forEach(el=>{const shown=mode==='read'||Number(el.dataset.reveal)<=state.step;el.classList.toggle('pending',!shown);el.setAttribute('aria-hidden',String(!shown));el.inert=!shown;});if(mode==='present'){ $('#step-label').textContent=`Schritt ${state.step+1} / ${s.steps}`;$('#counter').textContent=s.id+' / 15';$('.controls [data-action="prev"]').disabled=state.scene===0&&state.step===0;const end=state.scene===14;$('.controls [data-action="next"]').textContent=end?'Am Ende ✓':'Weiter →';$('.controls [data-action="next"]').disabled=end;document.querySelectorAll('.progress-track button').forEach((b,i)=>{b.classList.toggle('current',i===state.scene);if(i===state.scene)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});}}
function finishAnimations(){document.getAnimations().forEach(a=>{try{a.finish();}catch{a.cancel();}});}
function render(force=false){document.documentElement.classList.toggle('reduced',state.reduced);document.documentElement.classList.toggle('motion-override',!state.reduced);document.body.classList.toggle('reading',mode==='read');document.body.classList.toggle('presenter',mode==='presenter');if(mode==='presenter'){renderPresenter();return;}$('#mode-button').textContent=mode==='read'?'Präsentation':'Lesemodus';
 if(mode==='read'){if(force||lastRendered!==-2){$('#stage').innerHTML=scenes.map((s,i)=>`<section class="reading-section">${article(i,state)}<div class="reading-explanation"><h2>Zum Verstehen</h2><p>${esc(s.explanation)}</p><details><summary>Sprechtext · ${esc(speaker(s))} · ${s.duration} Sekunden</summary><p>${esc(notes[i]?.notes)}</p><p class="small">${esc(adaptCue(i))}</p></details><p class="small">${esc(notes[i]?.refs)}</p>${button('Hier präsentieren →','jump',`data-index="${i}"`)}</div></section>`).join('');lastRendered=-2;}applySteps();return;}
 const changed=lastRendered!==state.scene,focus=document.activeElement?.dataset;
 if(changed||force){$('#stage').innerHTML=article(state.scene,state);if(changed&&!state.reduced){const sameTask=lastRendered>=0&&scenes[lastRendered]?.task===scenes[state.scene].task;$('#stage article').animate([{opacity:0,transform:`translateX(${sameTask?32:70}px)`},{opacity:1,transform:'translateX(0)'}],{duration:sameTask?380:680,easing:'cubic-bezier(.16,1,.3,1)'});}if(force&&focus?.action){[...document.querySelectorAll(`[data-action="${focus.action}"]`)].find(x=>x.dataset.value===focus.value)?.focus({preventScroll:true});}}
 applySteps();if(changed||lastStep!==state.step)$('#announcement').textContent=`Szene ${state.scene+1}: ${scenes[state.scene].title}. Schritt ${state.step+1} von ${scenes[state.scene].steps}.`;
 lastRendered=state.scene;lastStep=state.step;$('.input-hint').classList.toggle('gone',state.scene>0||safeRead('lykeion-hint',false));
}
function renderPresenter(){const s=scenes[state.scene];$('#stage').innerHTML=`<div class="presenter-layout"><section class="presenter-notes"><div class="eyebrow">SPRECHERANSICHT · ${s.id} / 15 · ${esc(speaker(s))}</div><h1>${esc(s.title)}</h1><div class="presenter-script">${esc(notes[state.scene]?.notes||'')}</div><aside class="cue"><strong>Vortragshinweis</strong><p>${esc(adaptCue(state.scene))}</p></aside><p class="small">${esc(notes[state.scene]?.refs||'')}</p></section><aside class="presenter-sidebar"><div class="clock"><span>Gesamtzeit</span><strong id="timer-display">00:00</strong><span>Richtzeit hier: ${s.duration} Sekunden · Ziel gesamt: 11:55</span></div><div class="timer-controls">${button(state.timer.running?'Pause':'Timer starten','timer-toggle')}${button('Zurücksetzen','timer-reset')}</div><p id="timer-note" class="small"></p><div class="next-preview"><span>DANACH</span><h2>${scenes[state.scene+1]?.title||'Ende – Zeit für Rückfragen'}</h2><p>Aktuell: Schritt ${state.step+1} von ${s.steps}</p></div><div class="presenter-nav">${button('← Zurück','prev')}${button('Weiter →','next')}${button('Szene vollständig zeigen','full')}</div><p class="small">Mit dem Präsentationsfenster auf demselben Gerät gekoppelt. Für die Klasse den erweiterten zweiten Bildschirm verwenden.</p></aside></div>`;tick();}
function tick(){const d=$('#timer-display');if(!d)return;const sec=Math.floor(elapsed(state.timer)/1000);d.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;$('#timer-note').textContent=sec>=720?'Etwa 12 Minuten erreicht – den Abschluss im Blick behalten.':'';}
function post(type,payload={}){const message={type,session,sender,...payload};if(channel)channel.postMessage(message);else save(storageKey+'-message',{...message,nonce:crypto.randomUUID()});}
function publish(){const revision=Date.now();save(storageKey,{state,revision});post('state',{state,revision});}
function receive(message){if(!acceptsMessage(message,session,sender))return;if(!presenter&&message.type==='request')publish();if(!presenter&&message.type==='action')act(message.action,message.value);if(presenter&&message.type==='state'&&message.revision>=lastRevision){lastRevision=message.revision;state=message.state;render();}}
if(channel)channel.onmessage=e=>receive(e.data);else window.addEventListener('storage',e=>{if(e.key===storageKey+'-message'&&e.newValue){try{receive(JSON.parse(e.newValue));}catch{}}});
function act(action,value){if(presenter&&['next','prev','jump','full','timer-toggle','timer-reset','vote','life','mesotes','example'].includes(action)){post('action',{action,value});return;}finishAnimations();let force=false;switch(action){case'next':state=next(state,scenes);break;case'prev':state=prev(state,scenes);break;case'jump':mode='present';state=jump(state,value,scenes);closeModal();break;case'full':state=jump(state,state.scene,scenes,true);closeModal();break;case'start':state={...jump(state,0,scenes),vote:null,mesotes:1,life:2,example:0,timer:{elapsed:0,startedAt:0,running:false}};mode='present';closeModal();break;case'vote':case'life':case'mesotes':case'example':state={...state,[action]:Number(value)};force=true;break;case'timer-toggle':state={...state,timer:toggleTimer(state.timer)};break;case'timer-reset':state={...state,timer:{elapsed:0,startedAt:0,running:false}};break;case'reduced':state={...state,reduced:!state.reduced};save('lykeion-motion',state.reduced);closeModal();break;default:return;}if(!presenter)history.replaceState(null,'',`${location.pathname}${location.search}#${scenes[state.scene].id}/${state.step}`);render(force);publish();}
function openModal(type,title,html){returnFocus=document.activeElement;modal=type;$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;if(!$('#overlay').open)$('#overlay').showModal();}
function closeModal(){if(!modal)return;$('#overlay').close();modal=null;if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});}
function overview(){if(modal==='overview'){closeModal();return;}openModal('overview','Die 15 Szenen',`<div class="overview-grid">${scenes.map((s,i)=>button(`<span>${s.id} · ${s.task?'Aufgabe '+s.task:'Rahmen'}</span><strong>${esc(s.title)}</strong><small>${esc(speaker(s))} · ${s.duration} s</small>`,'jump',`data-index="${i}" class="${state.scene===i?'active':''}"`)).join('')}</div><p class="small">Ein Sprung öffnet den Anfang der Szene.</p>${button('Aktuelle Szene vollständig zeigen','full')}`);}
function sourceModal(id='Q1',range='',sceneIndex=state.scene){const s=scenes[sceneIndex],ids=id==='scene'?s.refs:[id],ranges=range?[range.split('-').map(Number)]:s.ranges;const lineText=`<div class="source-lines">${lines.map(l=>`<div class="text-line ${ranges.some(([a,b])=>l.line>=a&&l.line<=b)?'highlight':''}"><span class="line-number">${l.line}</span><span>${esc(l.text)}</span></div>`).join('')}</div>`;openModal('source','Quellen · '+s.short,`<p class="source-context">${esc(notes[sceneIndex]?.refs||'')}</p>${ids.map(sourceCard).join('')}${ids.includes('Q1')?`<div class="source-docs"><a target="_blank" rel="noopener" href="material/Aristoteles.pdf">Original-PDF ↗</a><a target="_blank" rel="noopener" href="material/Aristoteles_Arbeitsblatt_mit_Zeilen.pdf">Nummerierte PDF ↗</a></div><p class="small">Eigene feste Zeilenzählung · S. 1: 1–49 · S. 2: 50–75. Markiert sind die Belegstellen dieser Szene.</p>${lineText}`:`<p>${esc(s.explanation)}</p>`}`);if(ids.includes('Q1')){const target=$('.text-line.highlight');const container=$('.source-lines');if(target&&container)container.scrollTop=target.offsetTop-container.offsetTop-70;}}
function settings(){openModal('settings','Vortrag einrichten',`<div class="settings-grid"><section><h3>Vortragende</h3><label>Person A <input id="name-a" maxlength="40" value="${esc(state.names.A)}"></label><label>Person B <input id="name-b" maxlength="40" value="${esc(state.names.B)}"></label>${button('Namen speichern','save-names')}</section><section><h3>Darstellung</h3>${button(state.reduced?'Bewegung einschalten':'Bewegung reduzieren','reduced',`aria-pressed="${state.reduced}"`)}${button('Alle Szenen drucken','print')}${button('Neu beginnen','start')}</section></div><h3>Steuerung</h3><dl class="shortcuts"><dt>Leertaste / → / PageDown</dt><dd>Nächster Schritt, dann nächste Szene</dd><dt>← / PageUp</dt><dd>Einen Schritt zurück</dd><dt>Home / End</dt><dd>Erste / letzte Szene</dd><dt>G / Q / F</dt><dd>Übersicht / Quellen / Vollbild</dd><dt>Esc</dt><dd>Geöffnete Ansicht schließen</dd></dl><p class="small">Ein Klick oder kurzes Tippen auf freie Fläche geht weiter. Buttons und Quellen lösen nur ihre eigene Aktion aus. Szenen wechseln nie automatisch.</p>`);}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{openModal('help','Vollbild','<p>Dieser Browser lässt Vollbild hier nicht zu. Öffne die lokale Adresse in einem eigenen Browserfenster oder nutze dessen Vollbildfunktion.</p>');}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action;switch(a){case'close':closeModal();break;case'overview':overview();break;case'source':sourceModal(b.dataset.id,b.dataset.range,Number(b.closest('[data-scene]')?.dataset.scene??state.scene));break;case'source-scene':sourceModal('scene');break;case'settings':settings();break;case'fullscreen':fullscreen();break;case'read':mode=mode==='read'?'present':'read';lastRendered=-1;render(true);scrollTo(0,0);break;case'presenter':{publish();const url=new URL(location.href);url.searchParams.set('view','presenter');url.searchParams.set('session',session);const p=window.open(url,'lykeion-presenter-'+session,'popup,width=1200,height=850');if(!p)openModal('help','Sprecheransicht öffnen',`<p>Das zweite Fenster wurde blockiert.</p><a href="${esc(url.href)}" target="_blank" rel="noopener">Sprecheransicht als Tab öffnen ↗</a>`);break;}case'print':closeModal();buildPrint();window.print();break;case'dismiss-hint':save('lykeion-hint',true);$('.input-hint').classList.add('gone');break;case'save-names':state={...state,names:{A:$('#name-a').value.trim()||'Vincent',B:$('#name-b').value.trim()||'Mein Freund'}};save('lykeion-names',state.names);closeModal();render(true);publish();break;default:act(a,b.dataset.index??b.dataset.value);}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){e.preventDefault();closeModal();return;}if(modal==='overview'&&e.key.toLowerCase()==='g'){e.preventDefault();closeModal();return;}if(modal||e.repeat||e.ctrlKey||e.altKey||e.metaKey||e.target.closest('input,textarea,select,button,a,summary,[contenteditable="true"],[role="tab"]'))return;if(mode==='read')return;const k=e.key.toLowerCase(),actions={'arrowright':'next',' ':'next','pagedown':'next','arrowleft':'prev','pageup':'prev','home':'start','end':'end','g':'overview','q':'source','f':'fullscreen','?':'settings'};if(!actions[k])return;e.preventDefault();if(k==='g')overview();else if(k==='q')sourceModal('scene');else if(k==='f')fullscreen();else if(k==='?')settings();else if(k==='end')act('jump',14);else if(k==='home')act('jump',0);else act(actions[k]);});
window.addEventListener('hashchange',()=>{if(presenter)return;state={...state,...fromHash(location.hash,scenes)};render();publish();});
window.addEventListener('beforeprint',buildPrint);
async function init(){[notes,lines]=await Promise.all([fetch('./data/notes.json').then(r=>r.json()),fetch('./data/zeilen.json').then(r=>r.json())]);const saved=safeRead(storageKey,null);if(saved?.state&&(presenter||location.hash.match(/^#\d/)))state={...saved.state,...(presenter?{}:fromHash(location.hash,scenes))};shell();render();if(presenter)post('request');else{publish();if(saved?.state?.scene>0&&!location.hash)openModal('resume','Vortrag fortsetzen?',`<p>Zuletzt war Szene ${saved.state.scene+1} geöffnet: ${esc(scenes[saved.state.scene].title)}.</p>${button('Bei dieser Szene fortsetzen','jump',`data-index="${saved.state.scene}"`)} ${button('Neu beginnen','start')}`);}setInterval(tick,500);}
init().catch(error=>{app.innerHTML=`<main class="fatal"><h1>Die Präsentation konnte nicht laden.</h1><p>Bitte über den lokalen Server öffnen. Starte STARTEN.cmd und rufe http://localhost:4173 auf.</p><pre>${esc(error.message)}</pre></main>`;console.error(error);});



